package com.amora.app;
import android.app.*;import android.content.*;import android.content.pm.*;import android.os.*;import org.json.*;import java.time.*;import java.util.*;
public class CompanionService extends Service {
 static CompanionService active;static final long[] VIBRATE={0,400,150,400,150,600};final Handler handler=new Handler(Looper.getMainLooper());final java.util.concurrent.ExecutorService io=java.util.concurrent.Executors.newSingleThreadExecutor();boolean running=true;boolean syncing;String user="";int failures=0;
 final Runnable poll=new Runnable(){public void run(){if(!running)return;if(!syncing){syncing=true;io.execute(()->{try{sync();failures=0;}catch(Exception e){failures++;if(e.getMessage()!=null&&(e.getMessage().contains("HTTP 401")||e.getMessage().contains("HTTP 403")||e.getMessage().contains("HTTP 400")))handler.post(()->stopSelf());}finally{handler.post(()->syncing=false);}});}handler.postDelayed(this,15000);}};
 static void configure(Context c,JSONObject config)throws Exception{JSONObject s=new JSONObject(SecureStore.get(c));String uid=s.getString("user");SharedPreferences p=c.getSharedPreferences("amora",0);JSONObject oldAlerts=new JSONObject(p.getString("companion.alerts."+uid,"{}"));boolean hadAlerts=oldAlerts.optBoolean("messages")||oldAlerts.optBoolean("arrivals")||oldAlerts.optBoolean("sos");SharedPreferences.Editor edit=p.edit();if(config.has("device"))edit.putBoolean("companion.device."+uid,config.optBoolean("device"));if(config.has("apps"))edit.putBoolean("companion.apps."+uid,config.optBoolean("apps"));if(config.has("alerts"))edit.putString("companion.alerts."+uid,config.getJSONObject("alerts").toString());edit.apply();JSONObject alerts=new JSONObject(p.getString("companion.alerts."+uid,"{}"));if(!hadAlerts&&(alerts.optBoolean("messages")||alerts.optBoolean("arrivals")||alerts.optBoolean("sos")))p.edit().putLong("companion.enabledAt."+uid,System.currentTimeMillis()).remove("companion.cursor."+uid).apply();boolean enabled=p.getBoolean("companion.device."+uid,false)||alerts.optBoolean("messages")||alerts.optBoolean("arrivals")||alerts.optBoolean("sos");if(enabled)c.startForegroundService(new Intent(c,CompanionService.class));else c.stopService(new Intent(c,CompanionService.class));}
 @Override public void onCreate(){super.onCreate();active=this;}
 @Override public int onStartCommand(Intent intent,int flags,int id){if(intent==null){stopSelf();return START_NOT_STICKY;}if("stop".equals(intent.getAction())){stopByUser();return START_NOT_STICKY;}try{user=new JSONObject(SecureStore.get(this)).getString("user");PendingIntent stop=PendingIntent.getService(this,160,new Intent(this,CompanionService.class).setAction("stop"),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);Notification n=NativeBridge.notification(this,"amora-companion","(N)AMORA · status e avisos ativos","Acompanhamento que você autorizou. Toque em Parar para desativar.",stop);if(Build.VERSION.SDK_INT>=34)startForeground(260,n,ServiceInfo.FOREGROUND_SERVICE_TYPE_SPECIAL_USE);else startForeground(260,n);handler.removeCallbacks(poll);handler.post(poll);}catch(Exception e){NativeBridge.event("error","Abra o Amora para retomar status e avisos.");stopSelf();}return START_NOT_STICKY;}
 void sync()throws Exception{
  JSONObject s=AmoraApi.session(this);if(!running||!s.getString("user").equals(user)){handler.post(()->stopSelf());return;}SharedPreferences p=getSharedPreferences("amora",0);
  if(p.getBoolean("companion.device."+user,false)){JSONObject status=AmoraApi.call(this,new JSONObject());JSONArray people=status.optJSONArray("people");JSONObject mine=null;for(int i=0;people!=null&&i<people.length();i++)if(user.equals(people.getJSONObject(i).optString("user_id")))mine=people.getJSONObject(i);if(mine!=null&&mine.optBoolean("share_device")){AmoraApi.call(this,DeviceSnapshot.collect(this,p.getBoolean("companion.apps."+user,false)&&mine.optBoolean("share_apps")));}else p.edit().putBoolean("companion.device."+user,false).putBoolean("companion.apps."+user,false).apply();}
  JSONObject alerts=new JSONObject(p.getString("companion.alerts."+user,"{}"));if(alerts.optBoolean("messages")||alerts.optBoolean("arrivals")||alerts.optBoolean("sos")){
   String cursorKey="companion.cursor."+user,cursor=p.getString(cursorKey,"");boolean initial=cursor.isEmpty();if(initial)cursor=Instant.now().toString();JSONObject d=AmoraApi.call(this,new JSONObject().put("action","notifications").put("since",cursor));if(!running)return;JSONArray events=d.optJSONArray("events");for(int i=0;!initial&&events!=null&&i<events.length();i++)showEvent(this,events.getJSONObject(i),user,alerts);String server=d.getString("server_time");p.edit().putString(cursorKey,Instant.parse(server).minusSeconds(60).toString()).apply();
  }
 }
 static synchronized void showEvent(Context c,JSONObject event,String uid,JSONObject alerts)throws Exception{
  String kind=event.getString("kind"),key=event.getString("key");if(kind.equals("sos")?!alerts.optBoolean("sos"):kind.equals("arrival")?!alerts.optBoolean("arrivals"):!alerts.optBoolean("messages"))return;
  SharedPreferences p=c.getSharedPreferences("amora",0);long cutoff=p.getLong("companion.enabledAt."+uid,0);if(Instant.parse(event.getString("created_at")).toEpochMilli()<cutoff)return;String seenKey="companion.seen."+uid;JSONArray saved=new JSONArray(p.getString(seenKey,"[]"));for(int i=0;i<saved.length();i++)if(key.equals(saved.getString(i)))return;
  if(Build.VERSION.SDK_INT>=33&&c.checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=PackageManager.PERMISSION_GRANTED)return;
  boolean sos=kind.equals("sos"),vibrate=alerts.optBoolean("vibrate",true);String channel=sos?(vibrate?"amora-sos-vibrate-v1":"amora-sos-quiet-v1"):kind.equals("arrival")?"amora-place-v1":"amora-message-v1";
  NotificationManager m=c.getSystemService(NotificationManager.class);NotificationChannel nc=new NotificationChannel(channel,sos?(vibrate?"SOS com vibração":"SOS sem vibração"):kind.equals("arrival")?"Chegadas nos lugares":"Mensagens do vínculo",sos?NotificationManager.IMPORTANCE_HIGH:NotificationManager.IMPORTANCE_DEFAULT);nc.enableVibration(sos&&vibrate);if(sos&&vibrate)nc.setVibrationPattern(VIBRATE);m.createNotificationChannel(nc);
  PendingIntent open=PendingIntent.getActivity(c,Math.abs(key.hashCode()%10000)+300,new Intent(c,MainActivity.class).putExtra("route",event.optString("route","map")),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);
  String title=sos?"SOS · Seu amor pediu ajuda":kind.equals("arrival")?"Chegou com carinho ♡":"Nova mensagem · (N)AMORA";Notification.Builder builder=new Notification.Builder(c,channel).setSmallIcon(R.drawable.amora_icon).setContentTitle(title).setContentText(event.getString("body")).setStyle(new Notification.BigTextStyle().bigText(event.getString("body"))).setContentIntent(open).setAutoCancel(true).setCategory(sos?Notification.CATEGORY_ALARM:Notification.CATEGORY_MESSAGE).setVisibility(Notification.VISIBILITY_PRIVATE);
  m.notify(Math.abs(key.hashCode()%100000)+500,builder.build());JSONArray next=new JSONArray();for(int i=Math.max(0,saved.length()-199);i<saved.length();i++)next.put(saved.get(i));next.put(key);p.edit().putString(seenKey,next.toString()).apply();
 }
 void stopByUser(){SharedPreferences p=getSharedPreferences("amora",0);p.edit().putBoolean("companion.device."+user,false).putBoolean("companion.apps."+user,false).putString("companion.alerts."+user,"{}").apply();running=false;handler.removeCallbacks(poll);io.execute(()->{try{AmoraApi.call(this,new JSONObject().put("action","consent").put("device",false).put("apps",false));}catch(Exception ignored){}handler.post(()->stopSelf());});NativeBridge.event("companionStopped",true);}
 @Override public void onDestroy(){running=false;active=null;handler.removeCallbacks(poll);io.shutdown();super.onDestroy();}
 @Override public IBinder onBind(Intent intent){return null;}
}
